        return a

    # Helper function to calculate the least common multiple (LCM)
    def lcm(a, b):
        return abs(a * b) // gcd(a, b)

    # Iterate through the range to find the two numbers whose LCM is within the given range
    for i in range(1, R + 1):
        for j in range(i + 1, R + 1):
            if lcm(i, j) >= L and lcm(i, j) <= R:
                return [i, j]

