    def is_palindrome(n):
        return str(n) == str(n)[::-1]

    # Check if the number is a palindrome
    if is_palindrome(s):
        return s

    # Find the longest palindromic suffix of the number
    for i in range(len(s)):
        if is_palindrome(s[i:]):
            return s[:i+1]

    # If no palindromic suffix is found, return the original number
    return s
