def rearrange_bigger(n):
    # Convert the number to a string to easily manipulate its digits
    num_str = str(n)

    # Find the index where the largest digit is smaller than the next digit
    for i in range(len(num_str) - 2, -1, -1):
        if num_str[i] < num_str[i + 1]:
            # Find the smallest digit to swap with the current digit
            min_index = i + 1
            for j in range(i + 2, len(num_str)):
                if num_str[j] < num_str[min_index]:
                    min_index = j

            # Swap the digits at the found indices
            num_str[i], num_str[min_index] = num_str[min_index], num_str[i]

            # Convert the string back to an integer
            return int(''.join(num_str))

    # If no such arrangement exists, return the original number as it's already the largest possible number
    return n
```

