def comb_sort(nums):
    n = len(nums)
    gap = 1
    while gap < n:
        for i in range(0, n - gap, gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
        gap *= 2
    return nums
```

